async function main(ctx) {
  const input = ctx.input || {};

  const boardSlug = input.boardSlug != null ? String(input.boardSlug).trim() : '';
  const title = String(input.title || '').trim();

  if (!title) throw new Error('title is required');
  if (!boardSlug) throw new Error('boardSlug is required');

  const rawColumnName = input.columnName != null ? String(input.columnName).trim() : '';
  const rawColumnTitle = input.columnTitle != null ? String(input.columnTitle).trim() : '';
  const columnName = (rawColumnName || rawColumnTitle || '').trim();

  const out = {
    title,
    boardSlug,

    includeIds: Boolean(input.includeIds),

    // column selection hint
    columnName: columnName || undefined,
  };

  if (input.description != null && String(input.description).trim() !== '') out.description = String(input.description);

  if (input.pos != null && input.pos !== '') {
    const pos = Number(input.pos);
    if (Number.isFinite(pos)) out.pos = pos;
  }

  if (input.priority !== undefined) {
    out.priority = input.priority === null ? null : Number(input.priority);
  }

  // Unified assignee shape only
  if (input.assignee !== undefined) out.assignee = input.assignee;

  return out;
}

async function main(ctx) {
  const input = ctx.lastOutputOf('normalize_input') || {};
  const resp = ctx.lastOutputOf('get_board') || {};
  const body = resp.body || {};
  const data = body && body.data ? body.data : body;

  const board = data.board || data;
  const resolvedBoardId = String(board?.id || board?._id || '').trim();
  const resolvedBoardSlug = String(board?.slug || input.boardSlug || '').trim() || null;

  if (!resolvedBoardId) {
    throw new Error('Failed to resolve boardId from get-task-board response');
  }

  const columns = Array.isArray(data.columns) ? data.columns : (Array.isArray(board.columns) ? board.columns : []);
  if (!Array.isArray(columns) || columns.length === 0) {
    throw new Error('No columns found for boardSlug=' + String(input.boardSlug));
  }

  const byPos = [...columns].sort((a, b) => (Number(a?.pos ?? 0) - Number(b?.pos ?? 0)));

  let chosen;
  if (input.columnName) {
    const wanted = String(input.columnName).toLowerCase();
    chosen = columns.find((c) => String(c?.title ?? '').toLowerCase() === wanted)
      || columns.find((c) => String(c?.key ?? '').toLowerCase() === wanted)
      || columns.find((c) => String(c?.name ?? '').toLowerCase() === wanted);
    if (!chosen) throw new Error('No column matches columnName (title/key/name): ' + String(input.columnName));
  } else {
    chosen = byPos[0];
  }

  const resolvedColumnName = String(chosen?.title || chosen?.name || chosen?.key || '').trim();
  if (!resolvedColumnName) {
    throw new Error('Selected column has no usable title/name/key for columnName');
  }

  const args = {
    boardId: resolvedBoardId,
    title: String(input.title),
    columnName: resolvedColumnName
  };

  if (input.description !== undefined) args.description = input.description;
  if (input.pos !== undefined) args.pos = input.pos;
  if (input.priority !== undefined) args.priority = input.priority;

  if (input.assignee !== undefined) args.assignee = input.assignee;

  return {
    args,
    board: {
      id: resolvedBoardId,
      slug: resolvedBoardSlug,
      name: String(board?.name || '') || null
    },
    resolved: {
      boardId: resolvedBoardId,
      boardSlug: resolvedBoardSlug,
      columnName: resolvedColumnName
    }
  };
}

async function main(ctx) {
  const input = ctx.lastOutputOf('normalize_input') || {};

  const createResp = ctx.lastOutputOf('create_card') || {};
  const body = createResp.body || {};
  const data = body && body.data ? body.data : body;
  const card = data.card || data || {};

  const meta = ctx.lastOutputOf('pick_column_and_build_args') || {};
  const resolved = meta.resolved || {};
  const board = meta.board || {};

  const out = {
    success: true,
    title: String(card.title || input.title || ''),
    boardSlug: board.slug || resolved.boardSlug || input.boardSlug || null,
    boardName: board.name || null,
    columnName: resolved.columnName || null,
    description: card.description != null ? String(card.description) : '',
    priority: card.priority ?? null,
    pos: card.pos ?? null,
    archived: Boolean(card.archived),
    createdAt: card.createdAt || null,
    updatedAt: card.updatedAt || null
  };

  if (input.includeIds) {
    out.cardId = card.id || card._id || null;
    out.boardId = resolved.boardId || board.id || null;
  }

  return out;
}
